document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function i(n,e,i,s="info"){return`\n      <div class="insight-card ${s}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${i}</div>\n      </div>\n    `}const s=document.getElementById("pet-grooming-form"),t=document.getElementById("pet-grooming-result");s&&s.addEventListener("submit",function(s){s.preventDefault();const a=parseInt(document.getElementById("workstations").value),o=parseFloat(document.getElementById("equipment-cost").value),r=parseFloat(document.getElementById("renovation-cost").value),l=parseFloat(document.getElementById("additional-costs").value),d=parseFloat(document.getElementById("monthly-rent").value),c=parseFloat(document.getElementById("avg-service-price").value),p=parseFloat(document.getElementById("clients-per-day").value),v=parseFloat(document.getElementById("working-days").value),u=parseFloat(document.getElementById("staff-salaries").value),g=parseFloat(document.getElementById("supplies").value),m=parseFloat(document.getElementById("insurance").value),b=parseFloat(document.getElementById("other-expenses").value);if(a<=0||p<=0||c<=0)return t.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const h=o+r+l,w=p*v,$=w*c,f=.15*$,y=$+f,k=d+u+g+m+b,I=y-k,E=12*I,F=I/y*100,B=h/I,M=B/12,x=E/h*100,P=y/a,C=w/a,R=y/w;let D="info";I<0?D="warning":F>30&&(D="success");let L="info";x<20?L="warning":x>35&&(L="success");const S=4*a,A=p/S*100;t.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🐕 Pet Grooming Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${i("💰 Total Investment",n(h),"Initial capital required","info")}\n            ${i("📈 Monthly Profit",n(I),`Margin: ${e(F)}`,D)}\n            ${i("⏱️ Payback Period",`${M.toFixed(1)} years`,`${B.toFixed(0)} months`,M<=3?"success":"warning")}\n            ${i("🎯 Annual ROI",e(x),"Return on investment",L)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Grooming equipment & tools</span>\n                  <span>${n(o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Renovation & setup</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Licenses, permits & initial capital</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(h)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Monthly Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Grooming services (${Math.round(w)} clients × $${c})</span>\n                  <span>${n($)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Retail products (estimated 15%)</span>\n                  <span>${n(f)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Revenue</strong></span>\n                  <span><strong>${n(y)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Rent</span>\n                  <span>${n(d)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Staff salaries</span>\n                  <span>${n(u)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Supplies & materials</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Insurance</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other expenses</span>\n                  <span>${n(b)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(k)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>🔄 Operational Efficiency</h6>\n              <div class="metric-subtitle">\n                Revenue per station: <strong>${n(P)}/month</strong><br>\n                Clients per station: <strong>${Math.round(C)}/month</strong><br>\n                Average ticket: <strong>${n(R)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${A>70?"success":A<40?"warning":"info"}">\n              <h6>📊 Capacity Utilization</h6>\n              <div class="metric-subtitle">\n                Current utilization: <strong>${e(A)}</strong><br>\n                Maximum capacity: <strong>${S} clients/day</strong><br>\n                Growth potential: <strong>${e(100-A)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${I>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(E)}</strong><br>\n                Weekly profit: <strong>${n(12*I/52)}</strong><br>\n                Daily profit: <strong>${n(I/30)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>💡 Expansion Potential</h6>\n              <div class="metric-subtitle">\n                Additional services: <strong>+15-25% revenue</strong><br>\n                Mobile grooming: <strong>+30-50% premium</strong><br>\n                Corporate clients: <strong>stable income</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${F<25?"<li>⚠️ Low profitability. Consider increasing prices or reducing costs.</li>":""}\n              ${A<40?"<li>📍 Low utilization. Improve marketing or add services.</li>":""}\n              ${M>4?"<li>⏰ Long payback period. Optimize startup costs.</li>":""}\n              ${A>80?"<li>✅ High utilization! Consider expansion or premium pricing.</li>":""}\n              ${F>30?"<li>🎉 Excellent profitability! Consider additional locations.</li>":""}\n              <li>🛍️ Add retail pet products (food, toys, accessories) for additional revenue.</li>\n              <li>📱 Implement online booking and appointment reminders for better service.</li>\n              <li>🎓 Invest in staff training to improve service quality and upselling.</li>\n              <li>🚗 Consider mobile grooming services for premium clients.</li>\n              <li>🏥 Partner with veterinary clinics for comprehensive pet care.</li>\n              <li>💳 Offer package deals and membership programs for customer retention.</li>\n              <li>📊 Track peak hours and adjust pricing for demand optimization.</li>\n              <li>🏆 Develop specialty services (show grooming, breed-specific cuts) for higher margins.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.groomingBusinessData={"Grooming Stations":a,"Total Investment ($)":h,"Monthly Revenue ($)":y,"Monthly Expenses ($)":k,"Monthly Profit ($)":I,"Annual Profit ($)":E,"Profit Margin (%)":F,"Annual ROI (%)":x,"Payback Period (years)":M,"Monthly Clients":w,"Average Ticket ($)":R,"Utilization Rate (%)":A}}),window.downloadCSV=function(){if(!window.groomingBusinessData)return;const n=Object.entries(window.groomingBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),i=document.createElement("a");i.href=URL.createObjectURL(e),i.download="pet-grooming-business-plan.csv",i.click()}});